class LoginScreen extends StatefulWidget { final AppState state; const LoginScreen({super.key,required this.state}); @override State<LoginScreen> createState()=>_LoginScreenState(); }
class _LoginScreenState extends State<LoginScreen>{ final email=TextEditingController(); final password=TextEditingController(); UserRole role=UserRole.student;
 @override Widget build(BuildContext c)=>Scaffold(backgroundColor:bg,body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
  const SizedBox(height:30),Container(width:58,height:58,decoration:BoxDecoration(color:accent,borderRadius:BorderRadius.circular(18)),child:const Icon(Icons.bolt_rounded,color:bg,size:34)),const SizedBox(height:22),const Text('SkillForge',style:TextStyle(fontSize:36,fontWeight:FontWeight.w900)),const Text('Adaptive coding. Measurable growth.',style:TextStyle(color:muted,fontSize:15)),const SizedBox(height:34),GlassCard(child:Column(children:[TextField(controller:email,decoration:_dec('Email','student@skillforge.app',Icons.mail_outline)),const SizedBox(height:14),TextField(controller:password,obscureText:true,decoration:_dec('Password','••••••••',Icons.lock_outline)),const SizedBox(height:18),Align(alignment:Alignment.centerLeft,child:const Text('Sign in as',style:TextStyle(color:muted,fontSize:12))),const SizedBox(height:8),Wrap(spacing:8,children:UserRole.values.map((r)=>ChoiceChip(label:Text(r.name.toUpperCase()),selected:role==r,onSelected:(_)=>setState(()=>role=r),selectedColor:accent,backgroundColor:panel2,labelStyle:TextStyle(color:role==r?bg:Colors.white,fontWeight:FontWeight.w700))).toList()),const SizedBox(height:22),SizedBox(width:double.infinity,height:54,child:ElevatedButton(onPressed:(){widget.state.userName=role==UserRole.teacher?'Dr. Ananya Rao':role==UserRole.admin?'Admin Console':'Pavan Kalyan';widget.state.setRole(role);Navigator.pushReplacementNamed(c,'/home');},style:ElevatedButton.styleFrom(backgroundColor:accent,foregroundColor:bg,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(16))),child:const Text('Enter SkillForge  →',style:TextStyle(fontWeight:FontWeight.w900))),const SizedBox(height:12),const Text('Demo mode • no real credentials required',textAlign:TextAlign.center,style:TextStyle(color:muted,fontSize:11))]))
 ])))));
 Widget _dec(String a,String h,IconData i)=>InputDecoration(labelText:a,hintText:h,prefixIcon:Icon(i),filled:true,fillColor:panel2,border:OutlineInputBorder(borderRadius:BorderRadius.circular(14),borderSide:BorderSide.none)); }
